//! Stamps the commit the executable is built from, embeds the third-party notices, and gives the
//! executable its icon and version block: everything a user needs is in the one `.exe`.
//!
//! The commit makes a documentation link that cannot rot: the *About* window and `--version` link the
//! documentation of the exact revision that is running.
//!
//! The notices are generated by `cargo about` (`scripts/build.ps1`, which passes their path in
//! `QVT_NOTICES`); a build without them embeds a page saying where they come from, and the release
//! refuses such an executable.
//!
//! Nothing here fails a build. Source unpacked from an archive has no `.git`, a machine without git or
//! without the Windows SDK still builds: the commit then reads "unknown" and the executable has no icon.

use std::path::{Path, PathBuf};
use std::process::Command;

fn main() {
    watch_head();
    println!("cargo:rerun-if-changed=src");
    println!("cargo:rerun-if-changed=Cargo.toml");

    let commit = git(&["rev-parse", "HEAD"]).unwrap_or_else(|| "unknown".to_owned());
    let known = commit != "unknown";
    let short = if known {
        commit[..8].to_owned()
    } else {
        commit.clone()
    };
    // Untracked files count: a source file nobody added yet is still a difference from that commit.
    let dirty = known && git(&["status", "--porcelain"]).is_some_and(|s| !s.is_empty());

    println!("cargo:rustc-env=QVT_COMMIT={commit}");
    println!("cargo:rustc-env=QVT_COMMIT_SHORT={short}");
    println!(
        "cargo:rustc-env=QVT_DIRTY={}",
        if dirty { "-dirty" } else { "" }
    );
    // Documentation of an unknown build points at `main`, the best guess left.
    println!(
        "cargo:rustc-env=QVT_DOC_REF={}",
        if known { commit.as_str() } else { "main" }
    );

    embed_notices();

    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() == Ok("windows") {
        embed_resources(&short, dirty);
    }
}

/// Copies the notices named by `QVT_NOTICES` to `OUT_DIR/third-party-notices.html`, where the program
/// includes them, or writes a placeholder; `QVT_NOTICES_COMPLETE` tells which.
fn embed_notices() {
    println!("cargo:rerun-if-env-changed=QVT_NOTICES");
    let out = PathBuf::from(std::env::var("OUT_DIR").expect("cargo sets this"));
    let target = out.join("third-party-notices.html");
    let notices = std::env::var_os("QVT_NOTICES").map(PathBuf::from);
    if let Some(source) = &notices {
        println!("cargo:rerun-if-changed={}", source.display());
    }
    let copied = notices
        .as_deref()
        .is_some_and(|source| std::fs::copy(source, &target).is_ok());
    if !copied {
        if notices.is_some() {
            println!("cargo:warning=cannot read QVT_NOTICES, embedding a placeholder");
        }
        let placeholder = "<!doctype html><meta charset=\"utf-8\"><title>Third-party notices</title>\
            <p>This build was made without its third-party notices. Releases carry them; to generate \
            them, run <code>cargo about generate about.hbs</code> in the source.</p>";
        std::fs::write(&target, placeholder).expect("OUT_DIR is writable");
    }
    println!("cargo:rustc-env=QVT_NOTICES_COMPLETE={copied}");
}

/// The icon Explorer, the taskbar and *Send to* show, and the version block of the file's properties.
///
/// Compiled by `rc.exe` from the Windows SDK, which every MSVC toolchain installs with the linker: both
/// are PE resources, which no code can set at run time. `FileVersion` carries the commit,
/// `ProductVersion` the plain version, and a tree with uncommitted changes is flagged a private build.
fn embed_resources(commit: &str, dirty: bool) {
    let manifest = PathBuf::from(std::env::var("CARGO_MANIFEST_DIR").expect("cargo sets this"));
    let icon = manifest
        .join("assets")
        .join("icon")
        .join("quick-video-transcoder.ico");
    let license = manifest.join("LICENSE");
    println!("cargo:rerun-if-changed={}", icon.display());
    println!("cargo:rerun-if-changed={}", license.display());
    let Some(rc) = find_resource_compiler() else {
        println!("cargo:warning=rc.exe not found, building without icon or version block");
        return;
    };

    let version = std::env::var("CARGO_PKG_VERSION").expect("cargo sets this");
    let mut numbers = version
        .split(['.', '-'])
        .map(|part| part.parse::<u16>().unwrap_or(0));
    let mut next = || numbers.next().unwrap_or(0);
    let (major, minor, patch) = (next(), next(), next());
    let author = std::env::var("CARGO_PKG_AUTHORS").unwrap_or_default();
    let repository = std::env::var("CARGO_PKG_REPOSITORY").unwrap_or_default();
    // The LICENSE file holds the one copyright line; the resource repeats it.
    let copyright = std::fs::read_to_string(&license)
        .ok()
        .and_then(|text| {
            text.lines()
                .find(|line| line.starts_with("Copyright"))
                .map(str::to_owned)
        })
        .unwrap_or_default();
    let (flags, private) = if dirty {
        (
            "0x8", // VS_FF_PRIVATEBUILD
            "      VALUE \"PrivateBuild\", \"Built from a tree with uncommitted changes\\0\"\n",
        )
    } else {
        ("0x0", "")
    };

    // Resource id 1 is the application icon. FILEOS 0x40004 is VOS_NT_WINDOWS32, FILETYPE 1 VFT_APP,
    // the string block en-US Unicode. In rc.exe's language `\` starts an escape inside a quoted string:
    // every value goes through `rc_string`, and each `\0` written here is the terminator rc.exe expects.
    let script = format!(
        r#"1 ICON "{icon}"
1 VERSIONINFO
FILEVERSION {major},{minor},{patch},0
PRODUCTVERSION {major},{minor},{patch},0
FILEFLAGSMASK 0x3f
FILEFLAGS {flags}
FILEOS 0x40004
FILETYPE 0x1
FILESUBTYPE 0x0
BEGIN
  BLOCK "StringFileInfo"
  BEGIN
    BLOCK "040904b0"
    BEGIN
      VALUE "CompanyName", "{author}\0"
      VALUE "FileDescription", "Quick Video Transcoder\0"
      VALUE "FileVersion", "{version} ({commit})\0"
      VALUE "InternalName", "quick-video-transcoder\0"
      VALUE "LegalCopyright", "{copyright}. MIT License.\0"
      VALUE "OriginalFilename", "quick-video-transcoder.exe\0"
      VALUE "ProductName", "Quick Video Transcoder\0"
      VALUE "ProductVersion", "{version}\0"
      VALUE "Comments", "{repository}\0"
{private}    END
  END
  BLOCK "VarFileInfo"
  BEGIN
    VALUE "Translation", 0x409, 1200
  END
END
"#,
        icon = rc_string(&icon.display().to_string()),
        author = rc_string(&author),
        version = rc_string(&version),
        commit = rc_string(commit),
        copyright = rc_string(&copyright),
        repository = rc_string(&repository),
    );
    let out = PathBuf::from(std::env::var("OUT_DIR").expect("cargo sets this"));
    let source = out.join("quick-video-transcoder.rc");
    let compiled = out.join("quick-video-transcoder.res");
    if std::fs::write(&source, script).is_err() {
        println!("cargo:warning=cannot write the resource script, building without resources");
        return;
    }
    let status = Command::new(&rc)
        .args(["/nologo", "/fo"])
        .arg(&compiled)
        .arg(&source)
        .status();
    match status {
        // The executable only: the examples and tests have no use for it.
        Ok(status) if status.success() => println!(
            "cargo:rustc-link-arg-bin=quick-video-transcoder={}",
            compiled.display()
        ),
        _ => println!("cargo:warning=rc.exe failed, building without resources"),
    }
}

/// A value for a quoted string of an rc.exe script: `\` escapes as in C, a quote is doubled.
fn rc_string(value: &str) -> String {
    value.replace('\\', r"\\").replace('"', r#""""#)
}

/// The SDK's resource compiler: the developer prompt's variable first, then the newest Windows Kit.
fn find_resource_compiler() -> Option<PathBuf> {
    if let Some(dir) = std::env::var_os("WindowsSdkVerBinPath") {
        let candidate = Path::new(&dir).join("x64").join("rc.exe");
        if candidate.exists() {
            return Some(candidate);
        }
    }
    let program_files =
        std::env::var_os("ProgramFiles(x86)").or_else(|| std::env::var_os("ProgramFiles"))?;
    let bin = Path::new(&program_files)
        .join("Windows Kits")
        .join("10")
        .join("bin");
    // Version folders are zero-padded (10.0.NNNNN.0): sorted, the last is the newest.
    let mut versions: Vec<PathBuf> = std::fs::read_dir(bin)
        .ok()?
        .filter_map(Result::ok)
        .map(|entry| entry.path())
        .filter(|path| path.is_dir())
        .collect();
    versions.sort();
    versions.iter().rev().find_map(|version| {
        ["x64", "x86"]
            .iter()
            .map(|arch| version.join(arch).join("rc.exe"))
            .find(|candidate| candidate.exists())
    })
}

/// Re-runs this script when the checked-out commit changes. `.git/HEAD` alone is not enough: on a
/// branch it holds `ref: refs/heads/<name>` and does not change on commit, the ref file does (or
/// `packed-refs` once packed).
fn watch_head() {
    println!("cargo:rerun-if-changed=.git/HEAD");
    let Ok(head) = std::fs::read_to_string(".git/HEAD") else {
        return;
    };
    if let Some(reference) = head.trim().strip_prefix("ref: ") {
        println!("cargo:rerun-if-changed=.git/{reference}");
        println!("cargo:rerun-if-changed=.git/packed-refs");
    }
}

/// Runs git and returns its trimmed output, or `None` for any failure.
fn git(args: &[&str]) -> Option<String> {
    let output = Command::new("git").args(args).output().ok()?;
    output
        .status
        .success()
        .then(|| String::from_utf8(output.stdout).ok())
        .flatten()
        .map(|s| s.trim().to_owned())
}
